// === buildProject — identical to the frame-reviewed standalone builder ===
// Scores are GROUND TRUTH from TheSportsDB (via Prepare results). The LLM only
// writes copy: title, one caption line per match, closing. It can never change
// a score on screen.
function buildProject(config, prep, recap, probe) {
  const cfg = config || {};
  const clean = (v) => String(v == null ? '' : v).replace(/\s+/g, ' ').trim();
  const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const round2 = (n) => Math.round(n * 100) / 100;

  // ---- brand knobs --------------------------------------------------------
  const accent = clean(cfg.brandAccent) || '#C6FF3A';
  const bg = clean(cfg.brandBackground) || '#08110B';
  const font = clean(cfg.font) || 'Archivo';
  const brandName = clean(cfg.brandName) || 'FULL TIME';
  const handle = clean(cfg.handle) || '@yourclub';
  const ctaText = clean(cfg.ctaText) || 'Follow for every matchday';

  const hexToRgb = (hex) => {
    const m = /^#?([0-9a-f]{6})$/i.exec(clean(hex));
    if (!m) return null;
    const n = parseInt(m[1], 16);
    return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
  };
  const rgba = (hex, a) => {
    const c = hexToRgb(hex) || [198, 255, 58];
    return 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + a + ')';
  };
  const lighten = (hex, amt) => {
    const c = hexToRgb(hex) || [8, 17, 11];
    const h = (v) => ('0' + Math.min(255, v + amt).toString(16)).slice(-2);
    return '#' + h(c[0]) + h(c[1]) + h(c[2]);
  };

  // ---- data ---------------------------------------------------------------
  const matches = (Array.isArray(prep.matches) ? prep.matches : []).slice(0, 5);
  if (!matches.length) throw new Error('Prepare results delivered no matches — even the demo fallback is empty.');
  for (const m of matches) {
    if (!clean(m.home) || !clean(m.away)) throw new Error('A match is missing a team name: ' + JSON.stringify(m));
    if (!Number.isFinite(Number(m.homeScore)) || !Number.isFinite(Number(m.awayScore))) {
      throw new Error('A match has a non-numeric score: ' + JSON.stringify(m));
    }
  }
  const lines = Array.isArray(recap.lines) ? recap.lines : [];
  const league = clean(prep.league) || 'League';
  const roundLabel = clean(prep.roundLabel) || 'Latest results';
  const dateLine = clean(prep.dateLine);
  const title = clean(recap.title) || league + ' results';
  const closing = clean(recap.closing) || 'That is full time for this round';

  // ---- timing -------------------------------------------------------------
  // Scene transitions overlap their two scenes, so every non-last scene is
  // padded by its transition duration and the on-screen time stays as designed.
  const sceneBase = Math.min(6, Math.max(2.5, Number(cfg.sceneSeconds) || 3.4));
  const tSec = Math.min(0.8, Math.max(0.2, Number(cfg.transitionSeconds) || 0.45));
  const titleBase = 3.2;
  const titleT = 0.5;
  const outroBase = 3.6;

  // ---- cover video --------------------------------------------------------
  // Pinned portrait clip of a packed floodlit stadium at night, probed at
  // authoring time: 1440x2560 (same 9:16 aspect, no crop), 13.8 s, 19.5 MB.
  // The title scene (3.7 s) never outruns it.
  const COVER = 'https://videos.pexels.com/video-files/34930800/14796392_1080_1920_30fps.mp4';
  const coverVideo = clean(cfg.coverVideoOverride) === 'https://videos.pexels.com/video-files/34930800/14796393_1440_2560_30fps.mp4' ? COVER : (clean(cfg.coverVideoOverride) || COVER);
  const titleDur = round2(titleBase + titleT);
  const outroDur = outroBase;

  // ---- music guard --------------------------------------------------------
  // `probe` is the full HEAD response for cfg.musicUrl. Unreachable or
  // oversized music must never fail the render — it is simply dropped.
  const musicUrl = clean(cfg.musicUrl);
  const limit = Number(cfg.maxMusicBytes) > 0 ? Number(cfg.maxMusicBytes) : 5242880;
  const headers = (probe && probe.headers) || {};
  const musicBytes = Number(headers['content-length'] || headers['Content-Length'] || 0);
  const musicOk = !!musicUrl && Number(probe && probe.statusCode) === 200 && (!musicBytes || musicBytes <= limit);
  const musicSkipped = musicOk ? null : (!musicUrl ? 'musicUrl empty' : (Number(probe && probe.statusCode) !== 200 ? 'HEAD ' + (probe && probe.statusCode || 'failed') : musicBytes + ' bytes > ' + limit));

  // ---- adaptive type ------------------------------------------------------
  // Greedy word-wrap estimate. Archivo 900 uppercase runs ~0.68 em average,
  // mixed-case 900 ~0.50 em (calibrated on the rendered design sources).
  const wrapLines = (text, fontPx, boxPx, avgEm) => {
    const perLine = Math.max(4, Math.floor(boxPx / (fontPx * avgEm)));
    let n = 1;
    let used = 0;
    for (const w of String(text).split(' ')) {
      const need = used === 0 ? w.length : used + 1 + w.length;
      if (need <= perLine) { used = need; continue; }
      n += 1;
      used = Math.min(w.length, perLine);
    }
    return n;
  };

  const gradTop = lighten(bg, 12);
  const gradMid = lighten(bg, 5);

  // ---- title scene --------------------------------------------------------
  const roundLine = (league + ' · ' + roundLabel + (dateLine ? ' · ' + dateLine : '')).toUpperCase();
  const tLen = title.length;
  const titleSize = tLen <= 26 ? 76 : tLen <= 42 ? 66 : 58;
  const shadeSvg = "<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'><defs><linearGradient id='srShade' x1='0' y1='0' x2='0' y2='1'><stop offset='0' stop-color='" + bg + "' stop-opacity='0.75'/><stop offset='0.4' stop-color='" + bg + "' stop-opacity='0.45'/><stop offset='0.72' stop-color='" + bg + "' stop-opacity='0.88'/><stop offset='1' stop-color='" + bg + "' stop-opacity='0.98'/></linearGradient></defs><rect width='1080' height='1920' fill='url(#srShade)'/><path d='M-40 1150 L1120 1070 L1120 1086 L-40 1166 Z' fill='" + rgba(accent, 0.4) + "'/><path d='M-40 1210 L1120 1130 L1120 1174 L-40 1254 Z' fill='" + accent + "'/></svg>";

  const titleScene = {
    id: 'title',
    duration: titleDur,
    backgroundColor: bg,
    transition: 'slideup',
    transitionId: 'm1',
    transitionDuration: titleT,
    visuals: [
      { type: 'VIDEO', src: coverVideo, width: 1080, height: 1920, position: 'center-center', resize: 'cover', volume: 0, track: 0, enterBegin: 0, exitEnd: titleDur },
      { type: 'SVG', width: 1080, height: 1920, track: 1, enterBegin: 0, exitEnd: titleDur, svg: shadeSvg },
      {
        type: 'TEXT', x: 540, y: 170, anchor: 'top-center', track: 2, enterBegin: 0.15, enterEnd: 0.5, enterAnimation: 'fade', exitEnd: titleDur,
        style: { fontFamily: font, color: '#FFFFFF' },
        html: "<div style='text-align:center; color:rgba(255,255,255,0.85); font-size:23px; font-weight:700; letter-spacing:7px; text-shadow:0 2px 14px rgba(0,0,0,0.7);'>" + esc(handle.toUpperCase()) + '</div>',
      },
      {
        type: 'TEXT', x: 540, y: 1330, width: 940, anchor: 'top-center', track: 3, enterBegin: 0.2, enterEnd: 0.6, enterAnimation: 'circleopen', exitEnd: titleDur,
        style: { fontFamily: font, color: accent },
        html: "<div style='text-align:center; color:" + accent + "; font-size:34px; font-weight:900; letter-spacing:12px;'>" + esc(brandName.toUpperCase()) + "</div><div style='margin-top:14px; text-align:center; color:rgba(255,255,255,0.8); font-size:27px; font-weight:700; letter-spacing:3px;'>" + esc(roundLine) + '</div>',
      },
      {
        type: 'TEXT', x: 540, y: 1480, width: 940, anchor: 'top-center', track: 4, enterBegin: 0.55, enterEnd: 1.0, enterAnimation: 'smoothup', exitEnd: titleDur,
        style: { fontFamily: font, color: '#FFFFFF' },
        html: "<div style='text-align:center; color:#FFFFFF; font-size:" + titleSize + "px; line-height:1.05; font-weight:900; letter-spacing:-2px;'>" + esc(title) + '</div>',
      },
    ],
  };

  // ---- match scenes -------------------------------------------------------
  const cardSvg = "<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'><defs><radialGradient id='srBg' cx='0.5' cy='0.38' r='1'><stop offset='0' stop-color='" + gradTop + "'/><stop offset='0.55' stop-color='" + gradMid + "'/><stop offset='1' stop-color='" + bg + "'/></radialGradient></defs><rect width='1080' height='1920' fill='url(#srBg)'/><rect x='70' y='640' width='940' height='640' rx='36' fill='rgba(255,255,255,0.03)' stroke='" + rgba(accent, 0.4) + "' stroke-width='1.5'/><rect x='534' y='716' width='12' height='488' rx='6' fill='" + rgba(accent, 0.45) + "'/><rect x='70' y='640' width='940' height='12' rx='6' fill='" + accent + "'/></svg>";

  const nameSizesUsed = [];
  const matchScenes = matches.map((m, i) => {
    const isLastMatch = i === matches.length - 1;
    const dur = round2(sceneBase + tSec); // outro always follows, so every match scene is padded
    const home = clean(m.home).toUpperCase();
    const away = clean(m.away).toUpperCase();
    const hs = Number(m.homeScore);
    const as = Number(m.awayScore);
    const winner = hs > as ? 'home' : hs < as ? 'away' : 'draw';
    // Uppercase Archivo 900 runs ~0.78 em per character (measured on the
    // rendered frames), and CSS only wraps at spaces — so the size must also be
    // capped by the LONGEST WORD or a name like BOURNEMOUTH overflows its
    // 420 px column.
    const L = Math.max(home.length, away.length);
    const longestWord = Math.max(...(home + ' ' + away).split(' ').map((w) => w.length), 1);
    const tierSize = L <= 8 ? 56 : L <= 12 ? 50 : L <= 17 ? 44 : L <= 24 ? 38 : 32;
    const wordCap = Math.floor(420 / (longestWord * 0.8));
    const nameSize = Math.max(26, Math.min(tierSize, wordCap));
    nameSizesUsed.push(nameSize);
    const maxScore = Math.max(hs, as);
    const scoreSize = maxScore >= 100 ? 110 : maxScore >= 10 ? 150 : 170;
    const line = clean(lines[i] || '');
    const chipText = matches.length > 1 ? 'MATCH ' + (i + 1) + ' OF ' + matches.length : 'FULL TIME';

    const col = (name, score, side) => {
      const isWin = winner === side;
      const isDraw = winner === 'draw';
      const nameColor = isDraw || isWin ? '#FFFFFF' : '#98A29B';
      const scoreColor = isWin ? accent : 'rgba(255,255,255,0.92)';
      const bar = isWin ? "<div style='margin:20px auto 0; width:130px; height:8px; border-radius:4px; background:" + accent + ";'></div>" : '';
      return "<div style='height:130px; display:flex; align-items:flex-end; justify-content:center;'><div style='text-align:center; color:" + nameColor + '; font-size:' + nameSize + "px; line-height:1.12; font-weight:900; letter-spacing:0px;'>" + esc(name) + "</div></div><div style='margin-top:24px; text-align:center; color:" + scoreColor + '; font-size:' + scoreSize + "px; line-height:1; font-weight:900;'>" + (side === 'home' ? hs : as) + '</div>' + bar;
    };

    return {
      id: 'm' + (i + 1),
      duration: dur,
      backgroundColor: bg,
      transition: 'slideup',
      transitionId: isLastMatch ? 'outro' : 'm' + (i + 2),
      transitionDuration: tSec,
      visuals: [
        { type: 'SVG', width: 1080, height: 1920, track: 0, enterBegin: 0, exitEnd: dur, svg: cardSvg },
        {
          type: 'TEXT', x: 540, y: 470, anchor: 'center-center', track: 1, enterBegin: 0.1, enterEnd: 0.5, enterAnimation: 'fade', exitEnd: dur,
          style: { fontFamily: font, color: accent },
          html: "<span style='display:inline-block; background:" + accent + '; color:' + bg + "; padding:12px 34px; border-radius:10px; font-size:28px; font-weight:900; letter-spacing:6px;'>" + esc(chipText) + '</span>',
